// TH16 v1.00a Extra BossCard6 / spellEx 114 「秘儀「マターラドゥッカ」」
// Source: st07bs.ecl.txt:1681-1731 (BossCard6) + dependency BossCard6_at 1733-1760.
// Entry t=0, first shot t=90, one shard every 2 frames, interrupt/spellEx window 4800.
// Standalone shell: the 120-frame opening buffer sits inside the phase timer,
// so TIME_LIMIT = 120 + 4800 + 4.

const TIME_LIMIT: int = 4924;
const OPENING_BUFFER: int = 120;
const SOURCE_FIRE_START: int = 90;

// %A step 0.056112 rad = 585.269 BAM, kept as milli-BAM so 2400 shots do not drift.
const STEP_MILLI_BAM: int = 585269;

xformdef SHARD_TURN(delta: angle) {
    // OFFSCREEN a=200, b=0: shards are born 320+ px out and must survive until they enter the field.
    offscreen_keep(200);
    // STEP a=1, b=1, c=0, d=0, s<=-999990: one tick on the launch angle, then the segment
    // boundary applies +r and keeps the (unchanged) speed.
    wait(1);
    turn(delta);
}

async sub boss_pattern() {
    wait(OPENING_BUFFER);
    // entry: movePosTime(60, 4, 0.0f, 224.0f) -- mode 4 is quadratic deceleration.
    move_to(60, 0fx, 224fx, EASE_QUAD_OUT);
    // label +90: first shot at source t=90 (movePosTime is non-blocking, so wait 90 from entry).
    wait(SOURCE_FIRE_START);
    // %A = 1.570796f
    var a_milli: int = 16384000;
    loop {
        var ang: angle = (a_milli / 1000) as angle;
        // etSpeed(0, 1.0f + RANDF2*0.1f, 0.0f): speed is drawn first each shot.
        var us: fx = (rand(65536) - 32768) as fx / 32768;
        var spd: fx = 1fx + us * 0.1fx;
        // etExSet2(0, 2, 0, 16, 1, 1, 0, 0, RANDF2*0.2617994, -999999, ...): second draw.
        var ud: fx = (rand(65536) - 32768) as fx / 32768;
        var delta: int = (ud * 2730.68fx) as int;
        // Emitter = boss FINAL + etOffset(0, -24); etDist(-320) and ANIM entry
        // position -= 4*velocity give a net birth distance of -(320 + 4*speed) along the angle.
        var dist: fx = 0fx - (320fx + 4fx * spd);
        var sx: fx = $self_x + dist * cos(ang);
        var sy: fx = $self_y - 24fx + dist * sin(ang);
        _ = fire(TH16_SHARD, 2, sx, sy, spd, ang, SHARD_TURN(delta as angle), none);
        a_milli = a_milli + STEP_MILLI_BAM;
        if a_milli >= 65536000 { a_milli = a_milli - 65536000; }
        wait(2);
    }
}

async sub boss_main() {
    set_invuln(65535);
    // Boss context: setHurtbox(40,40) / setHitbox(48,48); circular branch halves the first value.
    set_hurtbox(20fx);
    set_hitbox(24fx);
    phase_begin(0, boss_pattern, TIME_LIMIT, 0);
    wait_spell();
}

sub main() {
    // Prior-card position is not part of the handoff data; the boss starts at the Boss entry
    // point (0,128) inside the previous moveLimit box, then BossCard6 moves it to (0,224).
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
